import { useState } from "react";
import StudentLayout from "./StudentLayout";

const ALL_SKILLS = [
  "React","Node.js","Django","Python","Java","SQL","Git","Docker","Figma","Tailwind CSS"
];
const WILAYAS = [
  "Alger","Oran","Constantine","Annaba","Sétif","Batna","Béjaïa","Tlemcen"
];
const LEVELS = ["L1","L2","L3","M1","M2"];
const LANG_LEVELS = ["Native","Fluent","Professional","Beginner"];

export default function StudentProfile() {
  // 1. State للبيانات الحقيقية (تكون فارغة في البداية لتنتظر المستخدم)
  const [profile, setProfile] = useState({
    firstName: "", lastName: "", email: "", phone: "",
    university: "", department: "", level: "L3", wilaya: "Alger",
    bio: "", github: "", skills: [], digitalCV: null,
    languages: [{ lang: "Arabic", level: "Native" }]
  });

  // 2. State للنسخة المؤقتة أثناء التعديل (Draft)
  const [draft, setDraft] = useState(profile);
  const [editing, setEditing] = useState(false);
  const [tab, setTab] = useState("info");

  // دالة لتحديث قيم الحقول النصية
  const handleChange = (e) => {
    const { name, value } = e.target;
    setDraft(prev => ({ ...prev, [name]: value }));
  };

  // دالة لاختيار/إلغاء المهارات
  const toggleSkill = (skill) => {
    setDraft(prev => ({
      ...prev,
      skills: prev.skills.includes(skill) 
        ? prev.skills.filter(s => s !== skill) 
        : [...prev.skills, skill]
    }));
  };

  // دالة حفظ البيانات
  const handleSave = () => {
    setProfile(draft);
    setEditing(false);
    console.log("Data to send to Django:", draft); // هنا ستربط مع Axios لاحقاً
  };

  return (
    <StudentLayout active="profile">
      <div className="max-w-4xl mx-auto p-4 md:p-8">
        
        {/* Header Section */}
        <div className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-3xl font-black text-slate-900">My Profile</h1>
            <p className="text-slate-500">Manage your personal and academic information</p>
          </div>
          {!editing ? (
            <button onClick={() => {setDraft(profile); setEditing(true);}} className="bg-blue-600 text-white px-6 py-2.5 rounded-xl font-bold text-sm shadow-lg hover:bg-blue-700 transition-all">
              Edit Profile
            </button>
          ) : (
            <div className="flex gap-2">
              <button onClick={() => setEditing(false)} className="bg-slate-100 text-slate-600 px-6 py-2.5 rounded-xl font-bold text-sm">Cancel</button>
              <button onClick={handleSave} className="bg-slate-900 text-white px-6 py-2.5 rounded-xl font-bold text-sm shadow-lg">Save Changes</button>
            </div>
          )}
        </div>

        {/* Tabs Navigation */}
        <div className="flex gap-2 bg-slate-100 p-1 rounded-2xl w-fit mb-8">
          {['info', 'skills', 'cv'].map((t) => (
            <button 
              key={t}
              onClick={() => setTab(t)}
              className={`px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${tab === t ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}
            >
              {t === 'info' ? '👤 Info' : t === 'skills' ? '⚡ Skills' : '📄 CV'}
            </button>
          ))}
        </div>

        <div className="grid gap-6">
          {/* TAB: Personal & Academic Info */}
          {tab === "info" && (
            <div className="space-y-6 animate-in fade-in duration-500">
              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
                <h3 className="font-black text-slate-900 mb-6 flex items-center gap-2">
                   <span className="w-1.5 h-6 bg-blue-600 rounded-full"></span> Personal Information
                </h3>
                <div className="grid md:grid-cols-2 gap-6">
                  <div></div>
                  <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">First Name</label>
                    <input name="firstName" disabled={!editing} value={editing ? draft.firstName : profile.firstName} onChange={handleChange} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm focus:ring-2 focus:ring-blue-500 transition-all" placeholder="Enter first name..." />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Last Name</label>
                    <input name="lastName" disabled={!editing} value={editing ? draft.lastName : profile.lastName} onChange={handleChange} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm focus:ring-2 focus:ring-blue-500 transition-all" placeholder="Enter last name..." />
                  </div>
                  <div className="md:col-span-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">University</label>
                    <input name="university" disabled={!editing} value={editing ? draft.university : profile.university} onChange={handleChange} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm focus:ring-2 focus:ring-blue-500 transition-all" placeholder="e.g. University of Constantine 2" />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Wilaya</label>
                    <select name="wilaya" disabled={!editing} value={editing ? draft.wilaya : profile.wilaya} onChange={handleChange} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm focus:ring-2 focus:ring-blue-500 transition-all appearance-none">
                      {WILAYAS.map(w => <option key={w} value={w}>{w}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Academic Level</label>
                    <select name="level" disabled={!editing} value={editing ? draft.level : profile.level} onChange={handleChange} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm focus:ring-2 focus:ring-blue-500 transition-all appearance-none">
                      {LEVELS.map(l => <option key={l} value={l}>{l}</option>)}
                    </select>
                  </div>
                </div>
              </div>
            
          )}

          {/* TAB: Skills Selection */}
          {tab === "skills" && (
            <div className="space-y-6 animate-in fade-in duration-500">
              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
                <h3 className="font-black text-slate-900 mb-2">Technical Skills</h3>
                <p className="text-xs text-slate-400 mb-6 italic">Select the technologies you have mastered.</p>
                <div className="flex flex-wrap gap-2">
                  {ALL_SKILLS.map(skill => (
                    <button
                      key={skill}
                      disabled={!editing}
                      onClick={() => toggleSkill(skill)}
                      className={`px-4 py-2 rounded-xl text-xs font-bold border transition-all ${
                        (editing ? draft.skills : profile.skills).includes(skill)
                        ? 'bg-blue-600 border-blue-600 text-white'
                        : 'bg-white border-slate-100 text-slate-500 hover:border-blue-200'
                      }`}
                    >
                      {skill}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}
          {/* TAB: CV Upload */}
          {tab === "cv" && (
            <div className="space-y-6 animate-in fade-in duration-500">
              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm text-center">
                <div className="text-5xl mb-4">📄</div>
                <h3 className="font-black text-slate-900 mb-2">Digital CV (PDF)</h3>
                <p className="text-xs text-slate-400 mb-8 max-w-xs mx-auto">This file will be automatically sent to companies when you apply for an internship.</p>
                
                <div className={`relative border-2 border-dashed rounded-[2rem] p-10 transition-all ${editing ? 'border-blue-200 hover:border-blue-400 cursor-pointer' : 'border-slate-100 bg-slate-50'}}>
                  {editing && (
                    <input 
                      type="file" 
                      accept=".pdf" 
                      className="absolute inset-0 opacity-0 cursor-pointer"
                      onChange={(e) => {
                        const file = e.target.files[0];
                        if(file) setDraft(prev => ({...prev, digitalCV: {name: file.name, size: (file.size/1024).toFixed(0) + " KB"}}));
                      }`}
                    />
                  )
                  
                  {(editing ? draft.digitalCV : profile.digitalCV) ? (
                    <div className="text-blue-600 font-bold">
                       ✅ {(editing ? draft.digitalCV.name : profile.digitalCV.name)}
                       <p className="text-[10px] text-slate-400 mt-1">{(editing ? draft.digitalCV.size : profile.digitalCV.size)}</p>
                    </div>
                  ) : (
                    <p className="text-sm font-bold text-slate-400">Drag & Drop your CV here or click to browse</p>
                  )}
                </div>
              </div>
            
          )}
        </div>
      </div>
    </StudentLayout>
  );
}
